), db AS (
  SELECT DISTINCT e.election_year, e.election_type, s.section_code
  FROM electoral.section_result r
  JOIN electoral.election e ON e.election_id=r.election_id
  JOIN territorial.section s ON s.section_id=r.section_id
  WHERE e.election_year IN (2018,2024)
), contrast AS (
  SELECT o.election_year, t.election_type, o.section_code,
         d.section_code IS NOT NULL AS loaded,
         s.section_id IS NOT NULL AS territorial_present
  FROM oficial o JOIN tipos t ON t.election_year=o.election_year
  LEFT JOIN db d ON d.election_year=o.election_year
                AND d.election_type=t.election_type AND d.section_code=o.section_code
  LEFT JOIN territorial.section s ON s.section_code=o.section_code
)
SELECT '01_resumen' AS bloque,election_year,election_type,
       COUNT(*) AS claves_referencia,
       COUNT(*) FILTER (WHERE loaded) AS cargadas,
       COUNT(*) FILTER (WHERE NOT loaded) AS faltantes,
       COUNT(*) FILTER (WHERE NOT loaded AND NOT territorial_present) AS faltantes_sin_territorial,
       COUNT(*) FILTER (WHERE NOT loaded AND territorial_present) AS faltantes_con_territorial
FROM contrast GROUP BY election_year,election_type ORDER BY election_year,election_type;

