    (2024, '3270'),
    (2024, '3271'),
    (2024, '3272'),
    (2024, '3273'),
    (2024, '3274'),
    (2024, '3275'),
    (2024, '3276'),
    (2024, '3277')
), db AS (
  SELECT DISTINCT e.election_year,e.election_type,s.section_code
  FROM electoral.section_result r
  JOIN electoral.election e ON e.election_id=r.election_id
  JOIN territorial.section s ON s.section_id=r.section_id
  WHERE (e.election_year=2018 AND e.election_type IN ('A','DF','DL','G','P','S'))
     OR (e.election_year=2024 AND e.election_type IN ('A','DF','DL','P','S'))
)
SELECT '03_cargadas_fuera_referencia' AS bloque,d.election_year,d.election_type,d.section_code
FROM db d LEFT JOIN oficial o ON o.election_year=d.election_year AND o.section_code=d.section_code
WHERE o.section_code IS NULL ORDER BY d.election_year,d.election_type,d.section_code::integer;
